//! Echoes the virtual COM port (SERCOM4, PD19/PD20, 115,200 baud, FIFO on)
//! through a `BufferedUart`, on the SERCOM's DRE, TXC, RXC and ERROR
//! vectors (`SERCOM4_0`, `_1`, `_2` and `_6` on the SG00). LED0 toggles with
//! each chunk echoed.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use embassy_executor::Spawner;
use panic_halt as _;
use pic32c_hal::gpio::{Level, Output};
use pic32c_hal::uart::{self, BufferedUart};
use pic32c_hal::{bind_interrupts, peripherals};
use static_cell::ConstStaticCell;

pic32cm_sg00_curiosity_pro::boot!();

bind_interrupts!(struct Irqs {
    SERCOM4_0 => uart::InterruptHandler<peripherals::SERCOM4>;
    SERCOM4_1 => uart::InterruptHandler<peripherals::SERCOM4>;
    SERCOM4_2 => uart::InterruptHandler<peripherals::SERCOM4>;
    SERCOM4_6 => uart::InterruptHandler<peripherals::SERCOM4>;
});

static TX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);
static RX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = pic32cm_sg00_curiosity_pro::init();
    let mut led = Output::new(p.PA20, Level::High);
    let uart = BufferedUart::new(p.SERCOM4, p.PD19, p.PD20, Irqs, TX.take(), RX.take(), uart::Config::default()).unwrap();
    let (mut tx, mut rx) = uart.split();
    let _ = tx.write_all(b"\r\npic32cm-sg00-curiosity-pro uart_echo\r\n").await;
    let mut buffer = [0u8; 64];
    loop {
        if let Ok(n) = rx.read(&mut buffer).await {
            let _ = tx.write_all(&buffer[..n]).await;
            led.toggle();
        }
    }
}
